<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CanteenWarehouseController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('canteen_manager')||$r->user()->canDo('canteen.manage'),403);}
public function index(Request $r){$this->manage($r);$products=DB::table('canteen_products as p')->leftJoin('canteen_stock_batches as b','b.canteen_product_id','=','p.id')->select('p.*',DB::raw('COALESCE(SUM(b.quantity_remaining),0) stock'))->groupBy('p.id')->orderBy('p.name')->get();$batches=DB::table('canteen_stock_batches as b')->join('canteen_products as p','p.id','=','b.canteen_product_id')->leftJoin('canteen_suppliers as s','s.id','=','b.canteen_supplier_id')->where('b.quantity_remaining','>',0)->select('b.*','p.name as product_name','p.unit','s.name as supplier_name')->orderByRaw('b.expires_on IS NULL')->orderBy('b.expires_on')->limit(100)->get();$suppliers=DB::table('canteen_suppliers')->where('active',1)->orderBy('name')->get();return view('canteen.warehouse',compact('products','batches','suppliers'));}
public function product(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','unit'=>'required|in:kg,g,l,ml,pcs','minimum_stock'=>'nullable|numeric|min:0']);DB::table('canteen_products')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function supplier(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','inn'=>'nullable|string|max:20','contact'=>'nullable|string|max:255','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255']);DB::table('canteen_suppliers')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function receipt(Request $r){$this->manage($r);$d=$r->validate(['canteen_product_id'=>'required|exists:canteen_products,id','canteen_supplier_id'=>'nullable|exists:canteen_suppliers,id','document_number'=>'nullable|string|max:100','received_on'=>'required|date','expires_on'=>'nullable|date|after_or_equal:received_on','quantity'=>'required|numeric|min:0.001','unit_price'=>'required|numeric|min:0']);DB::transaction(function()use($d,$r){$id=DB::table('canteen_stock_batches')->insertGetId(['canteen_product_id'=>$d['canteen_product_id'],'canteen_supplier_id'=>$d['canteen_supplier_id']??null,'document_number'=>$d['document_number']??null,'received_on'=>$d['received_on'],'expires_on'=>$d['expires_on']??null,'quantity_received'=>$d['quantity'],'quantity_remaining'=>$d['quantity'],'unit_price'=>$d['unit_price'],'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('canteen_stock_movements')->insert(['canteen_product_id'=>$d['canteen_product_id'],'canteen_stock_batch_id'=>$id,'type'=>'receipt','quantity'=>$d['quantity'],'reason'=>'Приход','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return back();}
public function writeoff(Request $r){$this->manage($r);$d=$r->validate(['canteen_product_id'=>'required|exists:canteen_products,id','quantity'=>'required|numeric|min:0.001','reason'=>'required|string|max:500']);$need=(float)$d['quantity'];DB::transaction(function()use(&$need,$d,$r){$batches=DB::table('canteen_stock_batches')->where('canteen_product_id',$d['canteen_product_id'])->where('quantity_remaining','>',0)->orderByRaw('expires_on IS NULL')->orderBy('expires_on')->lockForUpdate()->get();abort_if($batches->sum('quantity_remaining')<$need,422,'Недостаточно остатка');foreach($batches as $b){if($need<=0)break;$q=min($need,(float)$b->quantity_remaining);DB::table('canteen_stock_batches')->where('id',$b->id)->update(['quantity_remaining'=>(float)$b->quantity_remaining-$q,'updated_at'=>now()]);DB::table('canteen_stock_movements')->insert(['canteen_product_id'=>$d['canteen_product_id'],'canteen_stock_batch_id'=>$b->id,'type'=>'writeoff','quantity'=>-$q,'reason'=>$d['reason'],'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$need-=$q;}});return back();}
}